+// ReadContentHash reads the content hash for a specific session in a checkpoint.
+// Returns the content hash string (sha256:<hash>) or empty if not found.
+// sessionIndex is 0-based, use 0 for single-session checkpoints.
+func (s *GitStore) ReadContentHash(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
+	_ = ctx // Reserved for future use
+
+	tree, err := s.getSessionsBranchTree()
+	if err != nil {
+		return "", fmt.Errorf("sessions branch not found")
+	}
+
+	// Navigate sharded path: <id[:2]>/<id[2:]>/
+	basePath := checkpointID.ShardedPath()
+
+	// For multi-session, append session number subdirectory
+	sessionPath := basePath
+	if sessionIndex > 0 {
+		sessionPath = fmt.Sprintf("%s%d/", basePath, sessionIndex)
+	}
+
+	// Read content_hash.txt file
+	contentHashPath := sessionPath + "content_hash.txt"
+
+	// Navigate to the file
+	entry, err := tree.FindEntry(contentHashPath)
+	if err != nil {
+		// File not found - might be a legacy checkpoint without content hash
+		return "", nil
+	}
+
+	// Read the blob content
+	blob, err := s.repo.BlobObject(entry.Hash)
+	if err != nil {
+		return "", fmt.Errorf("failed to read content hash blob: %w", err)
+	}
+
+	reader, err := blob.Reader()
+	if err != nil {
+		return "", fmt.Errorf("failed to get blob reader: %w", err)
+	}
+	defer reader.Close()
+
+	content, err := io.ReadAll(reader)
+	if err != nil {
+		return "", fmt.Errorf("failed to read content hash: %w", err)
+	}
+
+	// Trim any whitespace
+	return strings.TrimSpace(string(content)), nil
+}
