 35→	hasher.Write([]byte(content))
 36→
 37→	return hex.EncodeToString(hasher.Sum(nil)), nil
 38→}
 39→
 40→// HashFileWithPath computes hash including the relative path for better change tracking
 41→func HashFileWithPath(absPath, relPath string) (string, error) {
 42→	file, err := os.Open(absPath)
 43→	if err != nil {
 44→		return "", fmt.Errorf("failed to open file %s: %w", absPath, err)
 45→	}
 46→	defer file.Close()
 47→
 48→	info, err := file.Stat()
 49→	if err != nil {
 50→		return "", fmt.Errorf("failed to stat file %s: %w", absPath, err)
 51→	}
 52→
 53→	hasher := sha256.New()
 54→
 55→	// Include relative path and executable bit in hash
 56→	fmt.Fprintf(hasher, "path:%s|exec:%t|", relPath, info.Mode()&0o111 != 0)
 57→
 58→	// Copy file content
 59→	if _, err := io.Copy(hasher, file); err != nil {
 60→		return "", fmt.Errorf("failed to hash file %s: %w", absPath, err)
 61→	}
 62→
 63→	return hex.EncodeToString(hasher.Sum(nil)), nil
 64→}
 65→
 66→// IsLargeFile checks if a file exceeds the size threshold for hashing
 67→func IsLargeFile(filePath string, thresholdMB int) (bool, error) {
 68→	info, err := os.Stat(filePath)
 69→	if err != nil {
 70→		return false, fmt.Errorf("failed to stat file %s: %w", filePath, err)
 71→	}
 72→
 73→	thresholdBytes := int64(thresholdMB * 1024 * 1024)
 74→	return info.Size() > thresholdBytes, nil
 75→}
 76→
 77→// ShouldHashFile determines if a file should be included in content hashing
 78→func ShouldHashFile(relPath string) bool {
 79→	// Skip hidden files and directories (except .gitignore, .gitattributes, etc)
 80→	base := filepath.Base(relPath)
 81→	if base != ".gitignore" && base != ".gitattributes" && len(base) > 0 && base[0] == '.' {
 82→		return false // Skip hidden files
 83→	}
 84→
 85→	// Check if file is in a hidden directory
 86→	for dir := filepath.Dir(relPath); dir != "." && dir != "/"; dir = filepath.Dir(dir) {
 87→		if filepath.Base(dir)[0] == '.' {
 88→			return false // Skip files in hidden directories
 89→		}
 90→	}
 91→
 92→	// Skip common build artifacts
 93→	switch filepath.Ext(relPath) {
 94→	case ".pyc", ".pyo", ".so", ".o", ".a", ".exe", ".dll":
 95→		return false
 96→	}
 97→
 98→	// Skip node_modules and similar
 99→	for _, part := range strings.Split(relPath, string(filepath.Separator)) {
100→		switch part {
101→		case "node_modules", "venv", ".venv", "__pycache__", "target", "dist", "build":
102→			return false
103→		}
104→	}
105→
106→	return true
107→}

