 10→
 11→// ComputeAggregateContentHash creates deterministic hash from file changes
 12→// Critical: Uses sorted file paths for rebase resilience
 13→func ComputeAggregateContentHash(fileHashes map[string]string) string {
 14→	if len(fileHashes) == 0 {
 15→		return "" // Empty changeset
 16→	}
 17→
 18→	// Sort files by path for deterministic ordering across rebases
 19→	var sortedPairs []string
 20→	for relPath, hash := range fileHashes {
 21→		sortedPairs = append(sortedPairs, fmt.Sprintf("%s:%s", relPath, hash))
 22→	}
 23→	sort.Strings(sortedPairs)
 24→
 25→	// Create aggregate hash: SHA256(path1:hash1|path2:hash2|...)
 26→	hasher := sha256.New()
 27→	for _, pair := range sortedPairs {
 28→		hasher.Write([]byte(pair + "|"))
 29→	}
 30→
 31→	return hex.EncodeToString(hasher.Sum(nil))
 32→}
 33→
 34→// ComputeAggregateFromLists creates deterministic hash from separate file lists
 35→// Useful when you have modified/new/deleted files tracked separately
 36→func ComputeAggregateFromLists(modified, new, deleted []string, hashFunc func(string) (string, error)) (string, error) {
 37→	if len(modified)+len(new)+len(deleted) == 0 {
 38→		return "", nil // No changes
 39→	}
 40→
 41→	fileHashes := make(map[string]string)
 42→
 43→	// Hash modified files
 44→	for _, path := range modified {
 45→		hash, err := hashFunc(path)
 46→		if err != nil {
 47→			return "", fmt.Errorf("failed to hash modified file %s: %w", path, err)
 48→		}
 49→		fileHashes[path] = hash
 50→	}
 51→
 52→	// Hash new files
 53→	for _, path := range new {
 54→		hash, err := hashFunc(path)
 55→		if err != nil {
 56→			return "", fmt.Errorf("failed to hash new file %s: %w", path, err)
 57→		}
 58→		fileHashes[path] = hash
 59→	}
 60→
 61→	// For deleted files, use a special marker
 62→	for _, path := range deleted {
 63→		fileHashes[path] = "DELETED"
 64→	}
 65→
 66→	return ComputeAggregateContentHash(fileHashes), nil
 67→}
 68→
 69→// NormalizeContentHash ensures consistent formatting of content hashes
 70→func NormalizeContentHash(hash string) string {
 71→	// Remove any sha256: prefix if present
 72→	hash = strings.TrimPrefix(hash, "sha256:")
 73→
 74→	// Lowercase for consistency
 75→	return strings.ToLower(hash)
 76→}
 77→
 78→// FormatContentHash formats a content hash for display/storage
 79→func FormatContentHash(hash string) string {
 80→	if hash == "" {
 81→		return ""
 82→	}
 83→
 84→	// Ensure it's normalized
 85→	hash = NormalizeContentHash(hash)
 86→
 87→	// Add sha256: prefix for clarity
 88→	return fmt.Sprintf("sha256:%s", hash)
 89→}
 90→
 91→// ValidateContentHash checks if a content hash is valid SHA256
 92→func ValidateContentHash(hash string) bool {
 93→	// Remove prefix if present
 94→	hash = NormalizeContentHash(hash)
 95→
 96→	// Check length (SHA256 is 64 hex characters)
 97→	if len(hash) != 64 {
 98→		return false
 99→	}
100→
101→	// Check if all characters are valid hex
102→	for _, r := range hash {
103→		if !((r >= '0' && r <= '9') || (r >= 'a' && r <= 'f')) {
104→			return false
105→		}
106→	}
107→
108→	return true
109→}

