  8→// FileChanges represents categorized file changes for content hashing.
  9→// This mirrors cli.FileChanges to avoid import cycles.
 10→type FileChanges struct {
 11→	Modified []string // Modified or staged files
 12→	New      []string // Untracked files
 13→	Deleted  []string // Deleted files (not used in content hashing)
 14→}
 15→
 16→// ComputeContentHashForChanges integrates with DetectFileChanges from state.go
 17→func ComputeContentHashForChanges(changes *FileChanges, repoRoot string) (string, error) {
 18→	if changes == nil || (len(changes.Modified)+len(changes.New)) == 0 {
 19→		return "", nil // No content to hash
 20→	}
 21→
 22→	fileHashes := make(map[string]string)
 23→
 24→	// Hash modified files
 25→	for _, relPath := range changes.Modified {
 26→		// Skip files we shouldn't hash
 27→		if !ShouldHashFile(relPath) {
 28→			continue
 29→		}
 30→
 31→		absPath := filepath.Join(repoRoot, relPath)
 32→
 33→		// Check if file is too large (skip files > 10MB by default)
 34→		isLarge, err := IsLargeFile(absPath, 10)
 35→		if err != nil {
 36→			// File might have been deleted between detection and hashing
 37→			continue
 38→		}
 39→		if isLarge {
 40→			// Skip large files to maintain performance
 41→			continue
 42→		}
 43→
 44→		hash, err := HashFileWithPath(absPath, relPath)
 45→		if err != nil {
 46→			return "", fmt.Errorf("failed to hash modified file %s: %w", relPath, err)
 47→		}
 48→		fileHashes[relPath] = hash
 49→	}
 50→
 51→	// Hash new files
 52→	for _, relPath := range changes.New {
 53→		// Skip files we shouldn't hash
 54→		if !ShouldHashFile(relPath) {
 55→			continue
 56→		}
 57→
 58→		absPath := filepath.Join(repoRoot, relPath)
 59→
 60→		// Check if file is too large
 61→		isLarge, err := IsLargeFile(absPath, 10)
 62→		if err != nil {
 63→			continue
 64→		}
 65→		if isLarge {
 66→			continue
 67→		}
 68→
 69→		hash, err := HashFileWithPath(absPath, relPath)
 70→		if err != nil {
 71→			return "", fmt.Errorf("failed to hash new file %s: %w", relPath, err)
 72→		}
 73→		fileHashes[relPath] = hash
 74→	}
 75→
 76→	// Deleted files excluded - don't contribute to content hash
 77→	// This is intentional: if a file is deleted, the content hash should change
 78→	// based on what remains, not what was removed
 79→
 80→	return ComputeAggregateContentHash(fileHashes), nil
 81→}
 82→
 83→// ComputeContentHashFromPaths computes content hash from file paths directly
 84→// This is useful when you have absolute paths instead of FileChanges
 85→func ComputeContentHashFromPaths(modifiedPaths, newPaths []string, repoRoot string) (string, error) {
 86→	if len(modifiedPaths)+len(newPaths) == 0 {
 87→		return "", nil // No content to hash
 88→	}
 89→
 90→	fileHashes := make(map[string]string)
 91→
 92→	// Process modified files
 93→	for _, absPath := range modifiedPaths {
 94→		relPath, err := filepath.Rel(repoRoot, absPath)
 95→		if err != nil {
 96→			continue // Skip files outside repo
 97→		}
 98→
 99→		if !ShouldHashFile(relPath) {
100→			continue
101→		}
102→
103→		// Check if file is too large
104→		isLarge, err := IsLargeFile(absPath, 10)
105→		if err != nil {
106→			continue
107→		}
108→		if isLarge {
109→			continue
110→		}
111→
112→		hash, err := HashFileWithPath(absPath, relPath)
113→		if err != nil {
114→			return "", fmt.Errorf("failed to hash modified file %s: %w", relPath, err)
115→		}
116→		fileHashes[relPath] = hash
117→	}
118→
119→	// Process new files
120→	for _, absPath := range newPaths {
121→		relPath, err := filepath.Rel(repoRoot, absPath)
122→		if err != nil {
123→			continue
124→		}
125→
126→		if !ShouldHashFile(relPath) {
127→			continue
128→		}
129→
130→		isLarge, err := IsLargeFile(absPath, 10)
131→		if err != nil {
132→			continue
133→		}
134→		if isLarge {
135→			continue
136→		}
137→
138→		hash, err := HashFileWithPath(absPath, relPath)
139→		if err != nil {
140→			return "", fmt.Errorf("failed to hash new file %s: %w", relPath, err)
141→		}
142→		fileHashes[relPath] = hash
143→	}
144→
145→	return ComputeAggregateContentHash(fileHashes), nil
146→}

