1067→// CreateBlobFromContent creates a blob object from in-memory content.
1068→// Exported for use by strategy package (session_test.go)
1069→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1070→	obj := repo.Storer.NewEncodedObject()
1071→	obj.SetType(plumbing.BlobObject)
1072→	obj.SetSize(int64(len(content)))
1073→
1074→	writer, err := obj.Writer()
1075→	if err != nil {
1076→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1077→	}
1078→
1079→	_, err = writer.Write(content)
1080→	if err != nil {
1081→		_ = writer.Close()
1082→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1083→	}
1084→	if err := writer.Close(); err != nil {
1085→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1086→	}
1087→
1088→	hash, err := repo.Storer.SetEncodedObject(obj)
1089→	if err != nil {
1090→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1091→	}
1092→	return hash, nil
1093→}
