1095→// copyMetadataDir copies all files from a directory to the checkpoint path.
1096→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1097→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1098→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1099→		if err != nil {
1100→			return err
1101→		}
1102→		if info.IsDir() {
1103→			return nil
1104→		}
1105→
1106→		// Skip symlinks to prevent reading files outside the metadata directory.
1107→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1108→		// then be captured in the checkpoint and stored in git history.
1109→		if info.Mode()&os.ModeSymlink != 0 {
1110→			return nil
1111→		}
1112→
1113→		// Get relative path within metadata dir
1114→		relPath, err := filepath.Rel(metadataDir, path)
1115→		if err != nil {
1116→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1117→		}
1118→
1119→		// Prevent path traversal via symlinks pointing outside the metadata dir
1120→		if strings.HasPrefix(relPath, "..") {
1121→			return fmt.Errorf("path traversal detected: %s", relPath)
1122→		}
1123→
1124→		// Create blob from file with secrets redaction
1125→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1126→		if err != nil {
1127→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1128→		}
1129→
1130→		// Store at checkpoint path
1131→		fullPath := basePath + relPath
1132→		entries[fullPath] = object.TreeEntry{
1133→			Name: fullPath,
1134→			Mode: mode,
1135→			Hash: blobHash,
1136→		}
1137→
1138→		return nil
1139→	})
1140→	if err != nil {
1141→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1142→	}
1143→	return nil
1144→}
1145→
1146→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1147→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1148→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1149→	info, err := os.Stat(filePath)
1150→	if err != nil {
1151→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1152→	}
1153→
1154→	mode := filemode.Regular
1155→	if info.Mode()&0o111 != 0 {
1156→		mode = filemode.Executable
1157→	}
1158→
1159→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1160→	if err != nil {
1161→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1162→	}
1163→
1164→	// Skip redaction for binary files — they can't contain text secrets and
1165→	// running string replacement on them would corrupt the data.
1166→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1167→	if binErr != nil || isBin {
1168→		hash, err := CreateBlobFromContent(repo, content)
1169→		if err != nil {
1170→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1171→		}
1172→		return hash, mode, nil
1173→	}
1174→
1175→	if strings.HasSuffix(treePath, ".jsonl") {
1176→		content, err = redact.JSONLBytes(content)
1177→		if err != nil {
1178→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to redact secrets: %w", err)
1179→		}
1180→	} else {
1181→		content = redact.Bytes(content)
1182→	}
1183→
1184→	hash, err := CreateBlobFromContent(repo, content)
1185→	if err != nil {
1186→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1187→	}
1188→	return hash, mode, nil
1189→}
