1211→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
1212→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
1213→// The agentType is used for reassembling chunks in the correct format.
1214→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
1215→	// Collect all transcript-related files
1216→	var chunkFiles []string
1217→	var hasBaseFile bool
1218→
1219→	for _, entry := range tree.Entries {
1220→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
1221→			hasBaseFile = true
1222→		}
1223→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
1224→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
1225→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
1226→			if idx > 0 {
1227→				chunkFiles = append(chunkFiles, entry.Name)
1228→			}
1229→		}
1230→	}
1231→
1232→	// If we have chunk files, read and reassemble them
1233→	if len(chunkFiles) > 0 {
1234→		// Sort chunk files by index
1235→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
1236→
1237→		// Check if base file should be included as chunk 0.
1238→		// NOTE: This assumes the chunking convention where the unsuffixed file
1239→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
1240→		if hasBaseFile {
1241→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
1242→		}
1243→
1244→		var chunks [][]byte
1245→		for _, chunkFile := range chunkFiles {
1246→			file, err := tree.File(chunkFile)
1247→			if err != nil {
1248→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
1249→					slog.String("chunk_file", chunkFile),
1250→					slog.String("error", err.Error()),
1251→				)
1252→				continue
1253→			}
1254→			content, err := file.Contents()
1255→			if err != nil {
1256→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
1257→					slog.String("chunk_file", chunkFile),
1258→					slog.String("error", err.Error()),
1259→				)
1260→				continue
1261→			}
1262→			chunks = append(chunks, []byte(content))
1263→		}
1264→
1265→		if len(chunks) > 0 {
1266→			result, err := agent.ReassembleTranscript(chunks, agentType)
1267→			if err != nil {
1268→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
1269→			}
1270→			return result, nil
1271→		}
1272→	}
1273→
1274→	// Fall back to reading base file (non-chunked or backwards compatibility)
1275→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
1276→		if content, err := file.Contents(); err == nil {
1277→			return []byte(content), nil
1278→		}
1279→	}
1280→
1281→	// Try legacy filename
1282→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
1283→		if content, err := file.Contents(); err == nil {
1284→			return []byte(content), nil
1285→		}
1286→	}
1287→
1288→	return nil, nil
1289→}
