 242→// homeRelativePath strips the $HOME/ prefix from an absolute path,
 243→// returning a home-relative path suitable for persisting in metadata.
 244→// Returns "" if the path is empty or not under $HOME.
 245→func homeRelativePath(absPath string) string {
 246→	if absPath == "" {
 247→		return ""
 248→	}
 249→	home, err := os.UserHomeDir()
 250→	if err != nil || home == "" {
 251→		return ""
 252→	}
 253→	prefix := home + string(filepath.Separator)
 254→	if !strings.HasPrefix(absPath, prefix) {
 255→		return ""
 256→	}
 257→	return absPath[len(prefix):]
 258→}
