 266→// resolveAgentType picks the best agent type from the context and existing state.
 267→// Priority: existing state (if specific) > context value > default fallback.
 268→func resolveAgentType(ctxAgentType agent.AgentType, state *SessionState) agent.AgentType {
 269→	if state != nil && isSpecificAgentType(state.AgentType) {
 270→		return state.AgentType
 271→	}
 272→	if ctxAgentType != "" {
 273→		return ctxAgentType
 274→	}
 275→	return DefaultAgentType
 276→}
