 425→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
 426→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
 427→// Returns empty string if no valid prompt is found.
 428→func ExtractFirstPrompt(content string) string {
 429→	if content == "" {
 430→		return ""
 431→	}
 432→
 433→	// Prompts are separated by "\n\n---\n\n"
 434→	// Find the first non-empty prompt
 435→	prompts := strings.Split(content, "\n\n---\n\n")
 436→	var firstPrompt string
 437→	for _, p := range prompts {
 438→		cleaned := strings.TrimSpace(p)
 439→		// Skip empty prompts or prompts that are just dashes/separators
 440→		if cleaned == "" || isOnlySeparators(cleaned) {
 441→			continue
 442→		}
 443→		firstPrompt = cleaned
 444→		break
 445→	}
 446→
 447→	if firstPrompt == "" {
 448→		return ""
 449→	}
 450→
 451→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
 452→}
