 471→// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
 472→// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
 473→// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
 474→// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
 475→func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) agent.AgentType {
 476→	// First, try to read from metadata.json (present in condensed/committed checkpoints)
 477→	metadataPath := checkpointPath + "/" + paths.MetadataFileName
 478→	if file, err := tree.File(metadataPath); err == nil {
 479→		if content, err := file.Contents(); err == nil {
 480→			var metadata checkpoint.CommittedMetadata
 481→			if err := json.Unmarshal([]byte(content), &metadata); err == nil && metadata.Agent != "" {
 482→				return metadata.Agent
 483→			}
 484→		}
 485→	}
 486→
 487→	// Fall back to detecting agent from config files (shadow branches don't have metadata.json)
 488→	// Check for Gemini config
 489→	if _, err := tree.File(".gemini/settings.json"); err == nil {
 490→		return agent.AgentTypeGemini
 491→	}
 492→	// Check for Claude config (either settings.local.json or settings.json in .claude/)
 493→	if _, err := tree.Tree(".claude"); err == nil {
 494→		return agent.AgentTypeClaudeCode
 495→	}
 496→
 497→	return agent.AgentTypeUnknown
 498→}
