 500→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
 501→func isOnlySeparators(s string) bool {
 502→	for _, r := range s {
 503→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
 504→			return false
 505→		}
 506→	}
 507→	return true
 508→}
