 510→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
 511→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
 512→// For single-session checkpoints, returns a slice with just the root prompt.
 513→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
 514→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
 515→		// Single session - just return the root prompt
 516→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
 517→		if prompt != "" {
 518→			return []string{prompt}
 519→		}
 520→		return nil
 521→	}
 522→
 523→	// Multi-session: read prompts from archived folders (0/, 1/, etc.) and root
 524→	prompts := make([]string, len(sessionIDs))
 525→
 526→	// Read archived session prompts (folders 0, 1, ... N-2)
 527→	for i := range sessionCount - 1 {
 528→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
 529→		prompts[i] = ReadSessionPromptFromTree(tree, archivedPath)
 530→	}
 531→
 532→	// Read the most recent session prompt (at root level)
 533→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
 534→
 535→	return prompts
 536→}
