 583→// OpenRepository opens the git repository with linked worktree support enabled.
 584→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
 585→// which is required for proper operation in git worktrees created via 'git worktree add'.
 586→//
 587→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
 588→// - Commits appear to succeed but are not persisted
 589→// - Refs are written to incorrect locations
 590→// - The worktree's HEAD/index don't get updated properly
 591→//
 592→// This happens because worktrees use .git as a file (pointing to the main repo)
 593→// rather than a directory, and go-git needs to route paths correctly between
 594→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
 595→//
 596→// The function first uses 'git rev-parse --show-toplevel' to find the repository
 597→// root, which works correctly even when called from a subdirectory within the repo.
 598→func OpenRepository() (*git.Repository, error) {
 599→	// First, find the repository root using git rev-parse --show-toplevel
 600→	// This works correctly from any subdirectory within the repository
 601→	repoRoot, err := GetWorktreePath()
 602→	if err != nil {
 603→		// Fallback to current directory if git command fails
 604→		// (e.g., if git is not installed or we're not in a repo)
 605→		repoRoot = "."
 606→	}
 607→
 608→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
 609→		EnableDotGitCommonDir: true,
 610→	})
 611→	if err != nil {
 612→		return nil, fmt.Errorf("failed to open repository: %w", err)
 613→	}
 614→	return repo, nil
 615→}
 616→
 617→// IsInsideWorktree returns true if the current directory is inside a git worktree
 618→// (as opposed to the main repository). Worktrees have .git as a file pointing
 619→// to the main repo, while the main repo has .git as a directory.
 620→// This function works correctly from any subdirectory within the repository.
 621→func IsInsideWorktree() bool {
 622→	// First find the repository root
 623→	repoRoot, err := GetWorktreePath()
 624→	if err != nil {
 625→		return false
 626→	}
 627→
 628→	gitPath := filepath.Join(repoRoot, gitDir)
 629→	gitInfo, err := os.Stat(gitPath)
 630→	if err != nil {
 631→		return false
 632→	}
 633→	return !gitInfo.IsDir()
 634→}
 635→
 636→// GetMainRepoRoot returns the root directory of the main repository.
 637→// In the main repo, this is the worktree path (repo root).
 638→// In a worktree, this parses the .git file to find the main repo.
 639→// This function works correctly from any subdirectory within the repository.
 640→//
 641→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
 642→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
 643→// See: https://git-scm.com/docs/gitrepository-layout
 644→func GetMainRepoRoot() (string, error) {
 645→	// First find the worktree/repo root
 646→	repoRoot, err := GetWorktreePath()
 647→	if err != nil {
 648→		return "", fmt.Errorf("failed to get worktree path: %w", err)
 649→	}
 650→
 651→	if !IsInsideWorktree() {
 652→		return repoRoot, nil
 653→	}
 654→
 655→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
 656→	gitFilePath := filepath.Join(repoRoot, gitDir)
 657→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
 658→	if err != nil {
 659→		return "", fmt.Errorf("failed to read .git file: %w", err)
 660→	}
 661→
 662→	gitdir := strings.TrimSpace(string(content))
 663→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
 664→
 665→	// Extract main repo root: everything before "/.git/"
 666→	idx := strings.LastIndex(gitdir, "/.git/")
 667→	if idx < 0 {
 668→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
 669→	}
 670→	return gitdir[:idx], nil
 671→}
 672→
 673→// GetGitCommonDir returns the path to the shared git directory.
 674→// In a regular checkout, this is .git/
 675→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
 676→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
 677→func GetGitCommonDir() (string, error) {
 678→	ctx := context.Background()
 679→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
 680→	cmd.Dir = "."
 681→	output, err := cmd.Output()
 682→	if err != nil {
 683→		return "", fmt.Errorf("failed to get git common dir: %w", err)
 684→	}
 685→
 686→	commonDir := strings.TrimSpace(string(output))
 687→
 688→	// git rev-parse --git-common-dir returns relative paths from the working directory,
 689→	// so we need to make it absolute if it isn't already
 690→	if !filepath.IsAbs(commonDir) {
 691→		commonDir = filepath.Join(".", commonDir)
 692→	}
 693→
 694→	return filepath.Clean(commonDir), nil
 695→}
