 697→// GetWorktreePath returns the absolute path to the current worktree root.
 698→// This is the working directory path, not the git directory.
 699→func GetWorktreePath() (string, error) {
 700→	ctx := context.Background()
 701→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
 702→	output, err := cmd.Output()
 703→	if err != nil {
 704→		return "", fmt.Errorf("failed to get worktree path: %w", err)
 705→	}
 706→	return strings.TrimSpace(string(output)), nil
 707→}
