 709→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
 710→// Works correctly from any subdirectory within the repository.
 711→func EnsureEntireGitignore() error {
 712→	// Get absolute path for the gitignore file
 713→	gitignoreAbs, err := paths.AbsPath(entireGitignore)
 714→	if err != nil {
 715→		gitignoreAbs = entireGitignore // Fallback to relative
 716→	}
 717→
 718→	// Read existing content
 719→	var content string
 720→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
 721→		content = string(data)
 722→	}
 723→
 724→	// All entries that should be in .entire/.gitignore
 725→	requiredEntries := []string{
 726→		"tmp/",
 727→		"settings.local.json",
 728→		"metadata/",
 729→		"logs/",
 730→	}
 731→
 732→	// Track what needs to be added
 733→	var toAdd []string
 734→	for _, entry := range requiredEntries {
 735→		if !strings.Contains(content, entry) {
 736→			toAdd = append(toAdd, entry)
 737→		}
 738→	}
 739→
 740→	// Nothing to add
 741→	if len(toAdd) == 0 {
 742→		return nil
 743→	}
 744→
 745→	// Ensure .entire directory exists
 746→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
 747→		return fmt.Errorf("failed to create .entire directory: %w", err)
 748→	}
 749→
 750→	// Append missing entries to gitignore
 751→	var sb strings.Builder
 752→	for _, entry := range toAdd {
 753→		sb.WriteString(entry + "\n")
 754→	}
 755→	content += sb.String()
 756→
 757→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
 758→		return fmt.Errorf("failed to write gitignore: %w", err)
 759→	}
 760→	return nil
 761→}
 762→
 763→// checkCanRewind checks if working directory is clean enough for rewind.
 764→// Returns (canRewind, reason, error). Shared by shadow and linear-shadow strategies.
 765→func checkCanRewind() (bool, string, error) {
 766→	repo, err := OpenRepository()
 767→	if err != nil {
 768→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 769→	}
 770→
 771→	worktree, err := repo.Worktree()
 772→	if err != nil {
 773→		return false, "", fmt.Errorf("failed to get worktree: %w", err)
 774→	}
 775→
 776→	status, err := worktree.Status()
 777→	if err != nil {
 778→		return false, "", fmt.Errorf("failed to get status: %w", err)
 779→	}
 780→
 781→	if status.IsClean() {
 782→		return true, "", nil
 783→	}
 784→
 785→	var modified, added, deleted []string
 786→	for file, st := range status {
 787→		// Skip .entire directory
 788→		if paths.IsInfrastructurePath(file) {
 789→			continue
 790→		}
 791→
 792→		// Skip untracked files
 793→		if st.Worktree == git.Untracked {
 794→			continue
 795→		}
 796→
 797→		switch {
 798→		case st.Staging == git.Added || st.Worktree == git.Added:
 799→			added = append(added, file)
 800→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
 801→			deleted = append(deleted, file)
 802→		case st.Staging == git.Modified || st.Worktree == git.Modified:
 803→			modified = append(modified, file)
 804→		}
 805→	}
 806→
 807→	if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
 808→		return true, "", nil
 809→	}
 810→
 811→	var msg strings.Builder
 812→	msg.WriteString("You have uncommitted changes:\n")
 813→	for _, f := range modified {
 814→		msg.WriteString(fmt.Sprintf("  modified:   %s\n", f))
 815→	}
 816→	for _, f := range added {
 817→		msg.WriteString(fmt.Sprintf("  added:      %s\n", f))
 818→	}
 819→	for _, f := range deleted {
 820→		msg.WriteString(fmt.Sprintf("  deleted:    %s\n", f))
 821→	}
 822→	msg.WriteString("\nPlease commit or stash your changes before rewinding.")
 823→
 824→	return false, msg.String(), nil
 825→}
 826→
 827→// checkCanRewindWithWarning checks working directory and returns a warning with diff stats.
 828→// Unlike checkCanRewind, this always returns canRewind=true but includes a warning message
 829→// with +/- line stats for uncommitted changes. Used by manual-commit strategy.
 830→func checkCanRewindWithWarning() (bool, string, error) {
 831→	repo, err := OpenRepository()
 832→	if err != nil {
 833→		// Can't open repo - still allow rewind but without stats
 834→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo can't be opened
 835→	}
 836→
 837→	worktree, err := repo.Worktree()
 838→	if err != nil {
 839→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree can't be accessed
 840→	}
 841→
 842→	status, err := worktree.Status()
 843→	if err != nil {
 844→		return true, "", nil //nolint:nilerr // Rewind allowed even if status can't be retrieved
 845→	}
 846→
 847→	if status.IsClean() {
 848→		return true, "", nil
 849→	}
 850→
 851→	// Get HEAD commit tree for comparison - if we can't get it, just return without stats
 852→	head, err := repo.Head()
 853→	if err != nil {
 854→		return true, "", nil //nolint:nilerr // Rewind allowed even without HEAD (e.g., empty repo)
 855→	}
 856→
 857→	headCommit, err := repo.CommitObject(head.Hash())
 858→	if err != nil {
 859→		return true, "", nil //nolint:nilerr // Rewind allowed even if commit lookup fails
 860→	}
 861→
 862→	headTree, err := headCommit.Tree()
 863→	if err != nil {
 864→		return true, "", nil //nolint:nilerr // Rewind allowed even if tree lookup fails
 865→	}
 866→
 867→	type fileChange struct {
 868→		status   string // "modified", "added", "deleted"
 869→		added    int
 870→		removed  int
 871→		filename string
 872→	}
 873→
 874→	var changes []fileChange
 875→	// Use repo root, not cwd - git status returns paths relative to repo root
 876→	repoRoot, err := GetWorktreePath()
 877→	if err != nil {
 878→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo root lookup fails
 879→	}
 880→
 881→	for file, st := range status {
 882→		// Skip .entire directory
 883→		if paths.IsInfrastructurePath(file) {
 884→			continue
 885→		}
 886→
 887→		// Skip untracked files
 888→		if st.Worktree == git.Untracked {
 889→			continue
 890→		}
 891→
 892→		var change fileChange
 893→		change.filename = file
 894→
 895→		switch {
 896→		case st.Staging == git.Added || st.Worktree == git.Added:
 897→			change.status = "added"
 898→			// New file - count all lines as added
 899→			absPath := filepath.Join(repoRoot, file)
 900→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
 901→				change.added = countLines(content)
 902→			}
 903→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
 904→			change.status = "deleted"
 905→			// Deleted file - count lines from HEAD as removed
 906→			if entry, err := headTree.File(file); err == nil {
 907→				if content, err := entry.Contents(); err == nil {
 908→					change.removed = countLines([]byte(content))
 909→				}
 910→			}
 911→		case st.Staging == git.Modified || st.Worktree == git.Modified:
 912→			change.status = "modified"
 913→			// Modified file - compute diff stats
 914→			var headContent, workContent []byte
 915→			if entry, err := headTree.File(file); err == nil {
 916→				if content, err := entry.Contents(); err == nil {
 917→					headContent = []byte(content)
 918→				}
 919→			}
 920→			absPath := filepath.Join(repoRoot, file)
 921→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
 922→				workContent = content
 923→			}
 924→			if headContent != nil && workContent != nil {
 925→				change.added, change.removed = computeDiffStats(headContent, workContent)
 926→			}
 927→		default:
 928→			continue
 929→		}
 930→
 931→		changes = append(changes, change)
 932→	}
 933→
 934→	if len(changes) == 0 {
 935→		return true, "", nil
 936→	}
 937→
 938→	// Sort changes by filename for consistent output
 939→	sort.Slice(changes, func(i, j int) bool {
 940→		return changes[i].filename < changes[j].filename
 941→	})
 942→
 943→	var msg strings.Builder
 944→	msg.WriteString("The following uncommitted changes will be reverted:\n")
 945→
 946→	totalAdded, totalRemoved := 0, 0
 947→	for _, c := range changes {
 948→		totalAdded += c.added
 949→		totalRemoved += c.removed
 950→
 951→		var stats string
 952→		switch {
 953→		case c.added > 0 && c.removed > 0:
 954→			stats = fmt.Sprintf("+%d/-%d", c.added, c.removed)
 955→		case c.added > 0:
 956→			stats = fmt.Sprintf("+%d", c.added)
 957→		case c.removed > 0:
 958→			stats = fmt.Sprintf("-%d", c.removed)
 959→		}
 960→
 961→		msg.WriteString(fmt.Sprintf("  %-10s %s", c.status+":", c.filename))
 962→		if stats != "" {
 963→			msg.WriteString(fmt.Sprintf(" (%s)", stats))
 964→		}
 965→		msg.WriteString("\n")
 966→	}
 967→
 968→	if totalAdded > 0 || totalRemoved > 0 {
 969→		msg.WriteString(fmt.Sprintf("\nTotal: +%d/-%d lines\n", totalAdded, totalRemoved))
 970→	}
 971→
 972→	return true, msg.String(), nil
 973→}
