 975→// countLines counts the number of lines in content.
 976→func countLines(content []byte) int {
 977→	if len(content) == 0 {
 978→		return 0
 979→	}
 980→	count := 1
 981→	for _, b := range content {
 982→		if b == '\n' {
 983→			count++
 984→		}
 985→	}
 986→	// Don't count trailing newline as extra line
 987→	if len(content) > 0 && content[len(content)-1] == '\n' {
 988→		count--
 989→	}
 990→	return count
 991→}
 992→
 993→// computeDiffStats computes added and removed line counts between old and new content.
 994→// Uses a simple line-based diff algorithm.
 995→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
 996→	oldLines := splitLines(oldContent)
 997→	newLines := splitLines(newContent)
 998→
 999→	// Build a set of old lines with counts
1000→	oldSet := make(map[string]int)
1001→	for _, line := range oldLines {
1002→		oldSet[line]++
1003→	}
1004→
1005→	// Check which new lines are truly new
1006→	for _, line := range newLines {
1007→		if oldSet[line] > 0 {
1008→			oldSet[line]--
1009→		} else {
1010→			added++
1011→		}
1012→	}
1013→
1014→	// Remaining old lines are removed
1015→	for _, count := range oldSet {
1016→		removed += count
1017→	}
1018→
1019→	return added, removed
1020→}
1021→
1022→// splitLines splits content into lines, preserving empty lines.
1023→func splitLines(content []byte) []string {
1024→	if len(content) == 0 {
1025→		return nil
1026→	}
1027→	s := string(content)
1028→	// Remove trailing newline to avoid empty last element
1029→	s = strings.TrimSuffix(s, "\n")
1030→	return strings.Split(s, "\n")
1031→}
