1039→// StageFilesContext describes what type of staging operation this is (for messages).
1040→type StageFilesContext string
1041→
1042→const (
1043→	// StageForSession is used when staging files for a session checkpoint.
1044→	StageForSession StageFilesContext = "session"
1045→	// StageForTask is used when staging files for a task checkpoint.
1046→	StageForTask StageFilesContext = "task"
