1049→// StageFiles stages modified, new, and deleted files to the git worktree.
1050→//
1051→// This function handles three categories of file changes:
1052→//  1. Modified files: existing files that have been changed
1053→//  2. New files: files that were created during the session
1054→//  3. Deleted files: files that were removed during the session
1055→//
1056→// Error Handling Strategy:
1057→//   - Individual file staging errors are logged to stderr but don't fail the operation
1058→//   - This ensures that partial staging succeeds even if some files have issues
1059→//   - If a modified file no longer exists, it's treated as a deletion
1060→//
1061→// The stageCtx parameter is used for user-facing messages to indicate whether
1062→// this is staging for a session checkpoint or a task checkpoint.
1063→func StageFiles(worktree *git.Worktree, modified, newFiles, deleted []string, stageCtx StageFilesContext) {
1064→	// Get repo root for resolving file paths
1065→	// This is critical because fileExists() uses os.Stat() which resolves relative to CWD,
1066→	// but worktree.Add/Remove resolve relative to repo root. If CWD != repo root,
1067→	// fileExists() could return false for existing files, causing worktree.Remove()
1068→	// to incorrectly delete them.
1069→	repoRoot := worktree.Filesystem.Root()
1070→
1071→	// Stage modified files
1072→	for _, file := range modified {
1073→		// Resolve path relative to repo root for existence check
1074→		absPath := filepath.Join(repoRoot, file)
1075→		if fileExists(absPath) {
1076→			if _, err := worktree.Add(file); err != nil {
1077→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
1078→			} else {
1079→				fmt.Fprintf(os.Stderr, "  Staged: %s\n", file)
1080→			}
1081→		} else {
1082→			// File was deleted - stage the deletion
1083→			if _, err := worktree.Remove(file); err != nil {
1084→				fmt.Fprintf(os.Stderr, "  File not found or deleted: %s\n", file)
1085→			}
1086→		}
1087→	}
1088→
1089→	// Stage new files
1090→	if len(newFiles) > 0 {
1091→		fmt.Fprintf(os.Stderr, "Staging %d new files created during %s:\n", len(newFiles), stageCtx)
1092→		for _, file := range newFiles {
1093→			if _, err := worktree.Add(file); err != nil {
1094→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
1095→			} else {
1096→				fmt.Fprintf(os.Stderr, "  Staged new file: %s\n", file)
1097→			}
1098→		}
1099→	}
1100→
1101→	// Stage deleted files
1102→	for _, file := range deleted {
1103→		if _, err := worktree.Remove(file); err != nil {
1104→			fmt.Fprintf(os.Stderr, "  Failed to stage deleted file %s: %v\n", file, err)
1105→		} else {
1106→			fmt.Fprintf(os.Stderr, "  Staged deleted file: %s\n", file)
1107→		}
1108→	}
1109→}
