1200→// ErrBranchNotFound is returned by DeleteBranchCLI when the branch does not exist.
1201→var ErrBranchNotFound = errors.New("branch not found")
1202→
1203→// DeleteBranchCLI deletes a git branch using the git CLI.
1204→// Uses `git branch -D` instead of go-git's RemoveReference because go-git v5
1205→// doesn't properly persist deletions when refs are packed (.git/packed-refs)
1206→// or in a worktree context. This is the same class of go-git v5 bug that
1207→// affects checkout and reset --hard (see HardResetWithProtection).
1208→//
1209→// Returns ErrBranchNotFound if the branch does not exist, allowing callers
1210→// to use errors.Is for idempotent deletion patterns.
1211→func DeleteBranchCLI(branchName string) error {
1212→	ctx := context.Background()
1213→
1214→	// Pre-check: verify the branch exists so callers get a structured error
1215→	// instead of parsing git's output string (which varies across locales).
1216→	// git show-ref exits 1 for "not found" and 128+ for fatal errors (corrupt
1217→	// repo, permissions, not a git directory). Only map exit code 1 to
1218→	// ErrBranchNotFound; propagate other failures as-is.
1219→	check := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
1220→	if err := check.Run(); err != nil {
1221→		var exitErr *exec.ExitError
1222→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1223→			return fmt.Errorf("%w: %s", ErrBranchNotFound, branchName)
1224→		}
1225→		return fmt.Errorf("failed to check branch %s: %w", branchName, err)
1226→	}
1227→
1228→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", branchName)
1229→	if output, err := cmd.CombinedOutput(); err != nil {
1230→		return fmt.Errorf("failed to delete branch %s: %s: %w", branchName, strings.TrimSpace(string(output)), err)
1231→	}
1232→	return nil
1233→}
