1239→	cmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
1240→	if err := cmd.Run(); err != nil {
1241→		return fmt.Errorf("branch %s not found: %w", branchName, err)
1242→	}
1243→	return nil
