1246→// HardResetWithProtection performs a git reset --hard to the specified commit.
1247→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
1248→// deletes untracked directories (like .entire/) even when they're in .gitignore.
1249→// Returns the short commit ID (7 chars) on success for display purposes.
1250→func HardResetWithProtection(commitHash plumbing.Hash) (shortID string, err error) {
1251→	ctx := context.Background()
1252→	hashStr := commitHash.String()
1253→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr) //nolint:gosec // hashStr is a plumbing.Hash, not user input
1254→	if output, err := cmd.CombinedOutput(); err != nil {
1255→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
1256→	}
1257→
1258→	// Return short commit ID for display
1259→	shortID = hashStr
1260→	if len(shortID) > 7 {
1261→		shortID = shortID[:7]
1262→	}
1263→	return shortID, nil
1264→}
