1266→// collectUntrackedFiles collects all untracked files in the working directory.
1267→// This is used to capture the initial state when starting a session,
1268→// ensuring untracked files present at session start are preserved during rewind.
1269→// Excludes protected directories (.git/, .entire/, and agent config directories).
1270→// Works correctly from any subdirectory within the repository.
1271→func collectUntrackedFiles() ([]string, error) {
1272→	// Get repository root to walk from there
1273→	repoRoot, err := GetWorktreePath()
1274→	if err != nil {
1275→		repoRoot = "." // Fallback to current directory
1276→	}
1277→
1278→	var untrackedFiles []string
1279→	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
1280→		if walkErr != nil {
1281→			return nil //nolint:nilerr // Skip filesystem errors during walk
1282→		}
1283→
1284→		// Get path relative to repo root
1285→		relPath, err := filepath.Rel(repoRoot, path)
1286→		if err != nil {
1287→			return nil //nolint:nilerr // Skip paths we can't make relative
1288→		}
1289→
1290→		// Skip directories
1291→		if info.IsDir() {
1292→			if isProtectedPath(relPath) {
1293→				return filepath.SkipDir
1294→			}
1295→			return nil
1296→		}
1297→
1298→		// Skip files in protected directories (shouldn't reach here due to SkipDir, but safety check)
1299→		if isProtectedPath(relPath) {
1300→			return nil
1301→		}
1302→
1303→		untrackedFiles = append(untrackedFiles, relPath)
1304→		return nil
1305→	})
1306→	if err != nil {
1307→		return nil, fmt.Errorf("failed to walk directory: %w", err)
1308→	}
1309→
1310→	return untrackedFiles, nil
1311→}
