1313→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
1314→// It checks the Entire-Session trailer first, then falls back to extracting from
1315→// the metadata directory path in the Entire-Metadata trailer.
1316→// Returns empty string if no session ID is found.
1317→func ExtractSessionIDFromCommit(commit *object.Commit) string {
1318→	// Try Entire-Session trailer first
1319→	if sessionID, found := trailers.ParseSession(commit.Message); found {
1320→		return sessionID
