1340→// createCommit creates a commit object
1341→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) { //nolint:unparam // already present in codebase
1342→	now := time.Now()
1343→	sig := object.Signature{
1344→		Name:  authorName,
1345→		Email: authorEmail,
1346→		When:  now,
1347→	}
1348→
1349→	commit := &object.Commit{
1350→		TreeHash:  treeHash,
1351→		Author:    sig,
1352→		Committer: sig,
1353→		Message:   message,
1354→	}
1355→
1356→	// Add parent if not a new branch
1357→	if parentHash != plumbing.ZeroHash {
1358→		commit.ParentHashes = []plumbing.Hash{parentHash}
1359→	}
1360→
1361→	obj := repo.Storer.NewEncodedObject()
1362→	if err := commit.Encode(obj); err != nil {
1363→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
1364→	}
1365→
1366→	hash, err := repo.Storer.SetEncodedObject(obj)
1367→	if err != nil {
1368→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
1369→	}
1370→
1371→	return hash, nil
1372→}
