1374→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
1375→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
1376→//
1377→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
1378→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
1379→// the session directory, e.g., auto-commit strategy's sharded metadata), then falls back to
1380→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
1381→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
1382→	// Helper to read first line from a file in tree
1383→	readFirstLine := func(path string) string {
1384→		file, err := tree.File(path)
1385→		if err != nil {
1386→			return ""
1387→		}
1388→		content, err := file.Contents()
1389→		if err != nil {
1390→			return ""
1391→		}
1392→		lines := strings.SplitN(content, "\n", 2)
1393→		if len(lines) > 0 && lines[0] != "" {
1394→			desc := strings.TrimSpace(lines[0])
1395→			// Remove markdown header prefix if present
1396→			return strings.TrimPrefix(desc, "# ")
1397→		}
1398→		return ""
1399→	}
1400→
1401→	// If metadataDir is provided, look there directly
1402→	if metadataDir != "" {
1403→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
1404→			return desc
1405→		}
1406→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
1407→			return desc
1408→		}
1409→		return NoDescription
1410→	}
1411→
1412→	// No metadataDir provided - first try looking at the root of the tree
1413→	// (used when the tree is already the session directory)
1414→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
1415→		return desc
1416→	}
1417→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
1418→		return desc
1419→	}
1420→
1421→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
1422→	// (used when the tree is the full worktree)
1423→	var desc string
1424→	//nolint:errcheck // We ignore errors here as we're just searching for a description
1425→	_ = tree.Files().ForEach(func(f *object.File) error {
1426→		if desc != "" {
1427→			return nil // Already found description
1428→		}
1429→		name := f.Name
1430→		if strings.Contains(name, ".entire/metadata/") {
1431→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
1432→				content, err := f.Contents()
1433→				if err != nil {
1434→					return nil //nolint:nilerr // Skip files we can't read, continue searching
1435→				}
1436→				lines := strings.SplitN(content, "\n", 2)
1437→				if len(lines) > 0 && lines[0] != "" {
1438→					desc = strings.TrimSpace(lines[0])
1439→					desc = strings.TrimPrefix(desc, "# ")
1440→				}
1441→			}
1442→		}
1443→		return nil
1444→	})
1445→
1446→	if desc != "" {
1447→		return desc
1448→	}
1449→	return NoDescription
1450→}
