1452→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
1453→// It checks local config first, then falls back to global config.
1454→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
1455→// operations to proceed even without git user config, which is especially useful
1456→// for internal metadata commits on branches like entire/checkpoints/v1.
1457→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1458→	// Get repository config (includes local settings)
1459→	cfg, err := repo.Config()
1460→	if err == nil {
1461→		name = cfg.User.Name
1462→		email = cfg.User.Email
1463→	}
1464→
1465→	// If not found in local config, try global config
1466→	if name == "" || email == "" {
1467→		globalCfg, err := config.LoadConfig(config.GlobalScope)
1468→		if err == nil {
1469→			if name == "" {
1470→				name = globalCfg.User.Name
1471→			}
1472→			if email == "" {
1473→				email = globalCfg.User.Email
1474→			}
1475→		}
1476→	}
1477→
1478→	// Provide sensible defaults if git user is not configured
1479→	if name == "" {
1480→		name = "Unknown"
1481→	}
1482→	if email == "" {
1483→		email = "unknown@local"
1484→	}
1485→
1486→	return name, email
1487→}
