1489→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
1490→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
1491→// This is used to capture branch metadata for checkpoints.
1492→func GetCurrentBranchName(repo *git.Repository) string {
1493→	head, err := repo.Head()
1494→	if err != nil || !head.Name().IsBranch() {
1495→		return ""
1496→	}
1497→	return head.Name().Short()
1498→}
