1500→// GetHeadTreeHash returns the hex string of HEAD's tree hash.
1501→// Returns an empty string if HEAD or its commit cannot be read (e.g., empty repository).
1502→func GetHeadTreeHash(repo *git.Repository) string {
1503→	head, err := repo.Head()
1504→	if err != nil {
1505→		return ""
1506→	}
1507→	commit, err := repo.CommitObject(head.Hash())
1508→	if err != nil {
1509→		return ""
1510→	}
1511→	return commit.TreeHash.String()
1512→}
