1514→// getMainBranchHash returns the hash of the main branch (main or master).
1515→// Returns ZeroHash if no main branch is found.
1516→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
1517→	// Try common main branch names
1518→	for _, branchName := range []string{branchMain, branchMaster} {
1519→		// Try local branch first
1520→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
1521→		if err == nil {
1522→			return ref.Hash()
1523→		}
1524→		// Try remote tracking branch
1525→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
1526→		if err == nil {
1527→			return ref.Hash()
1528→		}
1529→	}
1530→	return plumbing.ZeroHash
1531→}
1532→
1533→// GetDefaultBranchName returns the name of the default branch.
1534→// First checks origin/HEAD, then falls back to checking if main/master exists.
1535→// Returns empty string if unable to determine.
1536→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
1537→func GetDefaultBranchName(repo *git.Repository) string {
1538→	// Try to get the symbolic reference for origin/HEAD
1539→	// Use resolved=false to get the symbolic ref itself, then extract its target
1540→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
1541→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
1542→		target := ref.Target().String()
1543→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
1544→			return branchName
1545→		}
1546→	}
1547→
1548→	// Fallback: check if origin/main or origin/master exists
1549→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
1550→		return branchMain
1551→	}
1552→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
1553→		return branchMaster
1554→	}
1555→
1556→	// Final fallback: check local branches
1557→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
1558→		return branchMain
1559→	}
1560→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
1561→		return branchMaster
1562→	}
1563→
1564→	return ""
1565→}
1566→
1567→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
1568→// Returns (isOnDefault, currentBranchName).
1569→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
1570→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
1571→	currentBranch := GetCurrentBranchName(repo)
1572→	if currentBranch == "" {
1573→		return false, ""
1574→	}
1575→
1576→	defaultBranch := GetDefaultBranchName(repo)
1577→	if defaultBranch == "" {
1578→		// Can't determine default, check common names
1579→		if currentBranch == branchMain || currentBranch == branchMaster {
1580→			return true, currentBranch
1581→		}
1582→		return false, currentBranch
1583→	}
1584→
1585→	return currentBranch == defaultBranch, currentBranch
1586→}
