106→// CondenseSession condenses a session's shadow branch to permanent storage.
107→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
108→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
109→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
110→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID id.CheckpointID, state *SessionState) (*CondenseResult, error) {
111→	// Get shadow branch
112→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
113→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
114→	ref, err := repo.Reference(refName, true)
115→	if err != nil {
116→		return nil, fmt.Errorf("shadow branch not found: %w", err)
117→	}
118→
119→	// Extract session data from the shadow branch (with live transcript fallback).
120→	// Use tracked files from session state instead of collecting all files from tree.
121→	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini).
122→	// Pass live transcript path so condensation reads the current file rather than a
123→	// potentially stale shadow branch copy (SaveChanges may have been skipped if the
124→	// last turn had no code changes).
125→	// Pass CheckpointTranscriptStart for accurate token calculation (line offset for Claude, message index for Gemini).
126→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart)
127→	if err != nil {
128→		return nil, fmt.Errorf("failed to extract session data: %w", err)
129→	}
130→
131→	// Get checkpoint store
132→	store, err := s.getCheckpointStore()
133→	if err != nil {
134→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
135→	}
136→
137→	// Get author info
138→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
139→	attribution := calculateSessionAttributions(repo, ref, sessionData, state)
140→	// Get current branch name and tree hash
141→	branchName := GetCurrentBranchName(repo)
142→	commitTreeHash := GetHeadTreeHash(repo)
143→
144→	// Generate summary if enabled
145→	var summary *cpkg.Summary
146→	if settings.IsSummarizeEnabled() && len(sessionData.Transcript) > 0 {
147→		logCtx := logging.WithComponent(context.Background(), "attribution")
148→		summarizeCtx := logging.WithComponent(logCtx, "summarize")
149→
150→		// Scope transcript to this checkpoint's portion.
151→		// For Claude Code (JSONL), CheckpointTranscriptStart is a line offset.
152→		// For Gemini (JSON), CheckpointTranscriptStart is a message index.
153→		var scopedTranscript []byte
154→		if state.AgentType == agent.AgentTypeGemini {
155→			scopedTranscript = geminicli.SliceFromMessage(sessionData.Transcript, state.CheckpointTranscriptStart)
156→		} else {
157→			scopedTranscript = transcript.SliceFromLine(sessionData.Transcript, state.CheckpointTranscriptStart)
158→		}
159→		if len(scopedTranscript) > 0 {
160→			var err error
161→			summary, err = summarize.GenerateFromTranscript(summarizeCtx, scopedTranscript, sessionData.FilesTouched, state.AgentType, nil)
162→			if err != nil {
163→				logging.Warn(summarizeCtx, "summary generation failed",
164→					slog.String("session_id", state.SessionID),
165→					slog.String("error", err.Error()))
166→				// Continue without summary - non-blocking
167→			} else {
168→				logging.Info(summarizeCtx, "summary generated",
169→					slog.String("session_id", state.SessionID))
170→			}
171→		}
172→	}
173→
174→	// Write checkpoint metadata using the checkpoint store
175→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
176→		CheckpointID:                checkpointID,
177→		SessionID:                   state.SessionID,
178→		Strategy:                    StrategyNameManualCommit,
179→		Branch:                      branchName,
180→		CommitTreeHash:              commitTreeHash,
181→		Transcript:                  sessionData.Transcript,
182→		Prompts:                     sessionData.Prompts,
183→		Context:                     sessionData.Context,
184→		FilesTouched:                sessionData.FilesTouched,
185→		CheckpointsCount:            state.StepCount,
186→		EphemeralBranch:             shadowBranchName,
187→		AuthorName:                  authorName,
188→		AuthorEmail:                 authorEmail,
189→		Agent:                       state.AgentType,
190→		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
191→		CheckpointTranscriptStart:   state.CheckpointTranscriptStart,
192→		TokenUsage:                  sessionData.TokenUsage,
193→		InitialAttribution:          attribution,
194→		Summary:                     summary,
195→		SessionTranscriptPath:       homeRelativePath(state.TranscriptPath),
196→	}); err != nil {
197→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
198→	}
199→
200→	return &CondenseResult{
201→		CheckpointID:         checkpointID,
202→		SessionID:            state.SessionID,
203→		CheckpointsCount:     state.StepCount,
204→		FilesTouched:         sessionData.FilesTouched,
205→		TotalTranscriptLines: sessionData.FullTranscriptLines,
206→	}, nil
207→}
